"""Complete knowledge contracts with bounded, actual Docker/Go observations only."""
import gzip,hashlib,io,json,os,shutil,signal,subprocess,tarfile,time
from pathlib import Path
from native_base import Native,NativeEnvironmentUnavailable,plans,write_audit_atomic
from specs import SPECS

NEW='docker.io/library/busybox@sha256:a7dbc319b1438115a207e11930dc4bb3e643dcb3ec0bdd694bb36cd8fad289ec'
GO=Path('/opt/opsforge-tools/go1.27.3/bin/go');GO_SHA='5f5eb6d0b2fb6aa0bb5d5f8c5f1c944e0de955c925f0111af92a9d8f79680b5b'
TOOL_SHA='d2d91ab865a35f53679975721d2f5ea6421fcacc89a9e01bb1a40aa45cc0af8e'

def protected(obj):
 import re
 return ({x for x in (obj.get('RepoTags') or []) if not re.fullmatch('opsforge-s06-[a-f0-9]{24}:[ab]',x)},{x for x in (obj.get('RepoDigests') or []) if not re.fullmatch('opsforge-s06-[a-f0-9]{24}@sha256:[a-f0-9]{64}',x)})

class Owned(Native):
 def __init__(self):super().__init__();self.processes=[];self.process_intents=[];self.other_images={}
 def intent(self):
  write_audit_atomic(Path('native-intent.json'),{'token':self.token,'containers':self.containers,'volumes':self.volumes,'tags':self.tags,'networks':[],'host':self.host,'engine_id':self.approved_id,'image':self.image,'cli_sha256':self.tool_hash,'processes':self.process_intents})
 def other(self,image):
  obj=self.obj('image',image)
  if image!=self.image and image not in self.other_images:self.other_images[image]=(obj,protected(obj))
  return obj
 def process(self,argv,env,cwd,stdin=None,timeout=60):
  self.process_intents.append({'argv':argv,'cwd':str(cwd),'state':'intended-before-start','stdin_sha256':hashlib.sha256(stdin or b'').hexdigest()});self.intent()
  p=subprocess.Popen(argv,env=env,cwd=cwd,stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.PIPE,start_new_session=True);self.processes.append(p);self.process_intents[-1].update(pid=p.pid,state='started');self.intent();start=time.monotonic()
  try:out,err=p.communicate(stdin,timeout=timeout)
  except subprocess.TimeoutExpired:
   os.killpg(p.pid,signal.SIGKILL);out,err=p.communicate(timeout=3);self.trace.append({'argv':argv,'timeout':timeout,'stdout':out.decode(errors='replace'),'stderr':err.decode(errors='replace')});raise NativeEnvironmentUnavailable('trusted bounded native tool timed out')
  row={'argv':argv,'cwd':str(cwd),'pid':p.pid,'returncode':p.returncode,'stdout':out.decode(errors='replace'),'stderr':err.decode(errors='replace'),'seconds':time.monotonic()-start};self.trace.append(row);return p.returncode,out,err,row
 def finish(self):
  errors=[]
  for p in self.processes:
   if p.poll() is None:
    try:os.killpg(p.pid,signal.SIGKILL);p.communicate(timeout=3)
    except Exception as e:errors.append('own tool process cleanup '+str(e))
  for image,(before,refs) in self.other_images.items():
   try:
    after=self.obj('image',image);tags,digests=protected(after);assert after['Id']==before['Id'] and refs[0]<=tags and refs[1]<=digests
   except Exception as e:errors.append('approved other image preservation '+str(e))
  self.trace.append({'owned_native_processes_reaped':all(p.poll() is not None for p in self.processes),'additional_approved_images_preserved':not errors})
  try:self.intent()
  except Exception as e:errors.append('final owned intent audit write failed '+str(e))
  self.trace.append({'owned_cleanup_errors_before_base':list(errors)})
  try:super().finish()
  except Exception as e:
   errors.append('base cleanup or audit failed '+str(e));raise
  finally:
   # An audit I/O error must never skip ordinary resources or the own tmp.
   try:
    self.temp.cleanup()
    if self.root.exists():errors.append('owned temporary directory remains')
   except Exception as e:errors.append('owned temporary directory cleanup failed '+str(e))
   print('NATIVE_NETWORK_LEDGER:'+json.dumps({'networks':[],'errors':errors}),flush=True)
  assert not errors,errors;print('NETWORK_OWN_RESOURCES_CLEANED',flush=True)

def exited(s,c):
 for _ in range(50):
  obj=s.obj('container',c)
  if obj['State']['Status']=='exited':return obj
  time.sleep(.05)
 raise AssertionError('bounded native fixture did not exit')

def archive(s,image,role):
 obj=s.other(image);dest=s.root/(role+'.tar');s.call(['image','save','-o',str(dest),image],timeout=35);raw=dest.read_bytes();layers=[]
 with tarfile.open(fileobj=io.BytesIO(raw),mode='r:') as tar:
  members=tar.getmembers();assert len(members)<5000
  def read(name):
   m=tar.getmember(name);assert m.isfile() and m.size<=64*1024*1024;return tar.extractfile(m).read()
  manifest=json.loads(read('manifest.json'));assert len(manifest)==1;manifest=manifest[0];configraw=read(manifest['Config']);config=json.loads(configraw)
  config_digest='sha256:'+hashlib.sha256(configraw).hexdigest()
  # With the containerd image store inspect.Id may identify an OCI index,
  # whereas manifest.Config names the selected platform configuration blob.
  # Validate every actual blob plus RootFS/OS/arch, never equate these IDs.
  for member in members:
   if member.isfile() and member.name.startswith('blobs/sha256/'):
    assert hashlib.sha256(read(member.name)).hexdigest()==member.name.rsplit('/',1)[1]
  if manifest['Config'].startswith('blobs/sha256/'):assert config_digest=='sha256:'+manifest['Config'].rsplit('/',1)[1]
  assert config['os']==obj['Os'] and config['architecture']==obj['Architecture']
  expected=config['rootfs']['diff_ids'];assert expected==obj['RootFS']['Layers'] and len(expected)==len(manifest['Layers'])>0
  for path,diffid in zip(manifest['Layers'],expected):
   b=read(path)
   if b.startswith(b'\x1f\x8b'):b=gzip.decompress(b)
   assert 'sha256:'+hashlib.sha256(b).hexdigest()==diffid
   with tarfile.open(fileobj=io.BytesIO(b),mode='r:') as contents:
    entries=contents.getmembers();files=[{'path':m.name,'bytes':m.size,'mode':oct(m.mode),'kind':'file' if m.isfile() else 'other'} for m in entries]
   layers.append({'diff_id':diffid,'bytes':len(b),'entries':files})
 data={'image':image,'image_id':obj['Id'],'selected_platform_config_digest':config_digest,'image_size':obj['Size'],'archive_sha256':hashlib.sha256(raw).hexdigest(),'config':config,'verified_layers':layers,'scope':'Actual approved prebuilt config and layer contents; inspect image/index identity and platform config digest are distinct. No build, attestation provenance or incident attribution inferred.'};s.trace.append({'actual_image_archive_observation':data});return data

def history(s,mode):
 if mode in ('history-size-only','size-only-root-cause'):
  s.call(['history','--format','{{.Size}}',s.image]);raise AssertionError('size alone is neither instruction/config evidence nor a supported incident cause')
 result=s.call(['history','--no-trunc','--format','{{json .}}',s.image]);rows=[json.loads(line) for line in result.stdout.decode().splitlines() if line];assert rows and all('CreatedBy' in x and 'Size' in x for x in rows)
 data=archive(s,s.image,'history-image');assert data['config'].get('history')
 s.trace.append({'knowledge_history_observation':{'rows':rows,'rootfs_layer_count':len(data['verified_layers']),'history_entry_count':len(data['config']['history']),'empty_history_entries':sum(bool(x.get('empty_layer')) for x in data['config']['history']),'scope':'Real prebuilt evidence collection only, not APT404 or image-growth root-cause/fix reproduction.'}})

def compare(s,mode):
 first=s.other(s.image);second=s.other(NEW);assert first['Id']!=second['Id']
 if mode=='image-id-only':s.call(['image','inspect','--format','{{.Id}}',s.image,NEW]);raise AssertionError('different ID does not identify config/layer/metadata causes')
 a=archive(s,s.image,'old');b=archive(s,NEW,'new');assert a['config']['rootfs']['diff_ids']!=b['config']['rootfs']['diff_ids']
 versions=[]
 for n,image in [('old',s.image),('new',NEW)]:
  c=s.container('compare-'+n,tail=[image,'/bin/busybox']);obj=exited(s,c);assert obj['State']['ExitCode']==0;versions.append(s.call(['logs',c]).stdout.decode().splitlines()[0])
 assert versions[0]!=versions[1]
 s.trace.append({'knowledge_digest_comparison':{'old_image_or_index_id':a['image_id'],'new_image_or_index_id':b['image_id'],'old_selected_platform_config_digest':a['selected_platform_config_digest'],'new_selected_platform_config_digest':b['selected_platform_config_digest'],'old_layer_diff_ids':a['config']['rootfs']['diff_ids'],'new_layer_diff_ids':b['config']['rootfs']['diff_ids'],'old_history':a['config']['history'],'new_history':b['config']['history'],'versions':versions,'same_source_commit_incident_reproduced':False,'scope':'Actual different approved prebuilt versions. Complete causal-analysis method required; no same-commit build pair or invented original input.'}})

def platform(s,mode):
 info=json.loads(s.call(['info','--format','{{json .}}']).stdout)
 if mode=='tag-only':s.call(['image','inspect','--format','{{json .RepoTags}}',s.image]);raise AssertionError('tag availability is not target-platform execution')
 c=s.container('platform');uname=s.call(['exec',c,'uname','-m']).stdout.decode().strip();proof=s.token+'-target';actual=s.call(['exec',c,'printf','%s',proof]).stdout;assert actual==proof.encode()
