 s.trace.append({'knowledge_multiarch_gate':{'engine_OS':info['OSType'],'engine_architecture':info['Architecture'],'image_OS':s.base['Os'],'image_architecture':s.base['Architecture'],'uname_machine':uname,'actual_receipt_sha256':hashlib.sha256(actual).hexdigest(),'approved_platform_results':{'linux/amd64':'native fixture passed','linux/arm64':'no approved execution node; gate not passed'},'combined_publish_allowed':False,'scope':'One actual target platform plus complete multi-platform gate design; no arm64 run or manifest publication claimed.'}})

def artifact_identity(s,mode):
