 supplied=os.environ.get('OPSFORGE_DF_DEPENDENCY_SNAPSHOT');expected=json.loads((Path(__file__).parent/'snapshot-trusted-files.json').read_text())
 if not supplied:raise NativeEnvironmentUnavailable('trusted offline dependency snapshot not provisioned')
