   except Exception as e:errors.append('owned temporary directory cleanup failed '+str(e))
   print('NATIVE_NETWORK_LEDGER:'+json.dumps({'networks':[],'errors':errors}),flush=True)
  assert not errors,errors;print('NETWORK_OWN_RESOURCES_CLEANED',flush=True)

