 def other(self,image):
  obj=self.obj('image',image)
  if image!=self.image and image not in self.other_images:self.other_images[image]=(obj,protected(obj))
  return obj
 def process(self,argv,env,cwd,stdin=None,timeout=60):
  self.process_intents.append({'argv':argv,'cwd':str(cwd),'state':'intended-before-start','stdin_sha256':hashlib.sha256(stdin or b'').hexdigest()});self.intent()
