   assert 'sha256:'+hashlib.sha256(b).hexdigest()==diffid
   with tarfile.open(fileobj=io.BytesIO(b),mode='r:') as contents:
    entries=contents.getmembers();files=[{'path':m.name,'bytes':m.size,'mode':oct(m.mode),'kind':'file' if m.isfile() else 'other'} for m in entries]
   layers.append({'diff_id':diffid,'bytes':len(b),'entries':files})
